// Turns src/earth.js into public/earth-browser.js, a plain <script> that also
// works when index.html is opened straight from disk (file://).
import { readFileSync, writeFileSync } from "node:fs";

const src = readFileSync(new URL("./src/earth.js", import.meta.url), "utf8")
  .replace(/^export \{([^}]*)\};?\s*$/m, "window.EarthAPI = {$1};");
writeFileSync(
  new URL("./public/earth-browser.js", import.meta.url),
  "// Generated by build.js from src/earth.js. Do not edit.\n(() => {\n" + src + "})();\n",
);
console.log("Wrote public/earth-browser.js");
